class Solution:
 def findColumnWidth(self, grid):
  return [max(len(str(row[j])) for row in grid) for j in range(len(grid[0]))]

class Solution:
 def findPrefixScore(self, nums):
  m=s=0; out=[]
  for x in nums:
   m=max(m,x); s+=m+x; out.append(s)
  return out

class Solution:
 def rowAndMaximumOnes(self, mat):
  best=(-1,-1)
  for i,row in enumerate(mat):
   c=sum(row)
   if c>best[1]: best=(i,c)
  return list(best)

class Solution:
 def maxDivScore(self, nums, divisors):
  return min(divisors, key=lambda d: (-sum(x%d==0 for x in nums), d))

class Solution:
 def maximizeSum(self, nums, k):
  m=max(nums); return k*m+k*(k-1)//2

class Solution:
 def findThePrefixCommonArray(self, A, B):
  a=set(); b=set(); out=[]
  for x,y in zip(A,B):
   a.add(x); b.add(y); out.append(len(a&b))
  return out

class Solution:
 def isWinner(self, player1, player2):
  def score(a): return sum(x*(2 if any(a[j]==10 for j in range(max(0,i-2),i)) else 1) for i,x in enumerate(a))
  x,y=score(player1),score(player2)
  return 1 if x>y else 2 if y>x else 0

class Solution:
 def distinctDifferenceArray(self, nums):
  n=len(nums); out=[]
  for i in range(n): out.append(len(set(nums[:i+1]))-len(set(nums[i+1:])))
  return out
